#include <bits/stdc++.h>
using namespace std;
#define MOD 1000000007
#define MAXN 33
#define ll long long
ll bin[MAXN*2], n, m;

struct Matrix {
    ll mat[MAXN][MAXN];
    inline Matrix operator*(const Matrix &a) const {
        Matrix res;
        memset(res.mat, 0, sizeof(res.mat));
        for (int i=0; i<=m; ++i) {
            for (int j=0; j<=m; ++j) {
                for (int k=0; k<=m; ++k) {
                    res.mat[i][j] = (res.mat[i][j] + mat[i][k] * a.mat[k][j]) % MOD;
                }
            }
        }
        return res;
    }
};

int readInt() {
    int x=0, sign=1;
    char ch=getchar();
    while (ch<'0' || ch>'9') {
        if (ch=='-') sign=-1;
        ch=getchar();
    }
    while (ch>='0' && ch<='9') {
        x=x*10+ch-'0'; ch=getchar();
    }
    return x*sign;
}

int main() {
    n=readInt(); m=readInt();
    int n2=n, length=-1;
    while (n2) {
        length++;
        bin[length]=n2%m;
        n2=n2/m;
    }
    length++;
    Matrix ans;
    memset(ans.mat, 0, sizeof(ans.mat));
    for (int i=0; i<=m; ++i) ans.mat[0][i]=1;
    Matrix P[MAXN*2], S[MAXN*2], A[MAXN*2];
    for (int i=0; i<=m; ++i) {
        for (int j=0; j<=m; ++j) {
            A[0][i].mat[j][j]=1;
        }
    }
    for (int i=0; i<length; ++i) {
        for (int j=0; j<=m; ++j) {
            A[i][0].mat[j][j]=1;
        }
        if (i==0) {
            for (int j=0; j<m; ++j) {
                A[i][j].mat[m][m]=1;
                for (int k=0; k<m; ++k) {
                    if (k!=j) {
                        A[i][j].mat[k][k]=1;
                        for (int l=0; l<=m; ++l) A[i][j].mat[k][l]=1;
                    }
                }
            }
        } else {
            for (int j=0; j<m; ++j) {
                if (j==0) A[i][j]=S[i-1][0];
                else A[i][j]=S[i-1][j]*P[i-1][j-1];
            }
        }
        P[i][0]=A[i][0];
        for (int j=1; j<m; ++j) P[i][j]=P[i][j-1]*A[i][j];
        S[i][m-1]=A[i][m-1];
        for (int j=m-2; j>=0; --j) S[i][j]=A[i][j]*S[i][j+1];
    }
    int j=0;
    for (int i=length-1; i>=0; --i) {
        while (bin[i]>0) {
            ans=ans*A[i][j]; j++; if (j==m) j=0; bin[i]--;
        }
    }
    cout<<ans.mat[0][m]<<endl;
}
